    neighbors = []
    # r + r' = 0 => r' = -r
    r_prime = -r
    if r_prime != r:
        neighbors.append(r_prime)

    # r + r' = 1 => r' = 1 - r
    r_prime = 1 - r
    if r_prime != r:
        neighbors.append(r_prime)

    # r * r' = 1 => r' = 1/r
    if r != 0:
        r_prime = 1 / r
        if r_prime != r:
            neighbors.append(r_prime)
    return neighbors

def solve_for_target(start_r, start_val, target_r):
    f_values = {start_r: start_val}
    queue = [start_r]
    idx = 0
    while idx < len(queue):
        r = queue[idx]
        idx += 1
        if r == target_r:
            return f_values[target_r]
        for r_prime in get_neighbors(r):
            if r_prime not in f_values:
                f_values[r_prime] = 1 - f_values[r]
                queue.append(r_prime)
            else:
                if f_values[r_prime] == f_values[r]:
                    # This would mean an odd cycle exists
                    pass # We'll handle this if needed
    return None

