def find_path(start_r, target_r, max_nodes=100000):
    queue = collections.deque([(start_r, 0)])
    visited = {start_r: 0}

    while queue:
        r, dist = queue.popleft()
        if r == target_r:
            return dist

        if len(visited) > max_nodes:
            return None

        for r_prime in get_neighbors(r):
            if r_prime not in visited:
                visited[r_prime] = dist + 1
                queue.append((r_prime, dist + 1))
    return None

