def bidirectional_bfs(start_r, target_r, max_total_nodes=1000000):
    if start_r == target_r:
        return 0

    forward_visited = {start_r: 0}
    backward_visited = {target_r: 0}
    forward_queue = collections.deque([start_r])
    backward_queue = collections.deque([target_r])

    nodes_visited = 0

    while forward_queue and backward_queue and nodes_visited < max_total_nodes:
        # Expand forward
        if len(forward_queue) <= len(backward_queue):
            r = forward_queue.popleft()
            nodes_visited += 1
            for r_prime in get_neighbors(r):
                if r_prime in backward_visited:
                    return forward_visited[r] + 1 + backward_visited[r_prime]
                if r_prime not in forward_visited:
                    forward_visited[r_prime] = forward_visited[r] + 1
                    forward_queue.append(r_prime)
        else:
            # Expand backward
            r = backward_queue.popleft()
            nodes_visited += 1
            for r_prime in get_neighbors(r):
                if r_prime in forward_visited:
                    return backward_visited[r] + 1 + forward_visited[r_prime]
                if r_prime not in backward_visited:
                    backward_visited[r_prime] = backward_visited[r] + 1
                    backward_queue.append(r_prime)

    return None

